\vspace{+0.5em}


\noindent \textbf{If the path $R$ exists:} since $R$ is a subgraph of $\mathcal{F}^+$ then $y_R+y_{\ensuremath{\overrightarrow{v}}} \geq y_{P_{[s^-,|P|]}}+\ensuremath{\overrightarrow{v}} >y_{P_{|P|}}$, thus we have $V(\omepluse{R}) \cap W_{[m,+\infty]}=\emptyset$. Then there exists $\ind{6}=\max\{i:\omeplus{R}_i \in V(W)\}$. Moreover, we have $\ind{6}\geq \ind{5}\geq |R|$ and since $\omeplus{R}_{\ind{6}} \in \mathcal{F}^+$ then there exists $d<d' \leq |P|$ such that $\mathrm{pos}(P_{d'})=\omeplus{R}_{\ind{6}}$. Let $C'=R_{[\ind{6},\ind{6}+|R|-1]}$. By definition of $\ind{6}$ and $R$, the free zone $\mathcal{F}$ is split at position $W_{\ind{6}}=\mathrm{pos}(P_{d'})$ by $\omeplus{C'}$ into $(\mathcal{F}'^-, \mathcal{F}'^+)$. Note that since $R_1=\mathrm{pos}(P_d)$ with $d<d'$ then $R_1 \in V(\mathcal{F}^-)$. Moreover, since $R_{[1,\ind{6}]}$ is a path of $\mathcal{F}$ and since $V(R_{[1,\ind{6}]}) \cap V(\omeplus{C'})=\{R_{\ind{6}}\}$ then $R_{[1,\ind{6}]}$ is a subgraph of $\mathcal{F}'^-$ and since $\ind{6}\geq |R|$ then $C'-\ensuremath{\overrightarrow{v}}=R_{[\ind{6}-|R|+1,\ind{6}]}$ is a subgraph of $\mathcal{F}'^-$. Thus $P_{d'}$ is a dominant tile and the lemma is true.

\vspace{+0.5em}

\noindent \textbf{If $\omepluse{D_{[\ind{1},\ind{2}]}}$ is a subgraph of $\mathcal{F}^+$:} in this case by lemma \ref{lem:freezone} and since $D_{[\ind{1},\ind{2}]}$ is a good candidate segment, then the path assembly $P_{[1,s^-]} \cdot F_{[1,\ind{1}]} \cdot \omeplus{F_{[\ind{1},\ind{2}]}}$ is producible by $\mathcal{T}$,\emph{i.e.} the segment $F_{[\ind{1},\ind{2}]}$ is pumpable in $P_{[1,s^-]} \cdot F_{[1,\ind{2}]}$. Now, consider the decomposition $(A^i)_{1\leq i \leq \ell}$ of $P_{[s^+,|P|]}-\ensuremath{\overrightarrow{v}}$ in extremum arcs in $\mathcal{F}$. By lemma \ref{lem:uturn:ordered}, this decomposition is equivalent to the one of $W_{[n,+\infty]}-\ensuremath{\overrightarrow{v}}$. By lemma \ref{lem:fork:ordered}, this decomposition is positive. By lemma \ref{lem:existsStraddle:prel}, there exists $1\leq k < \ell$ such that $\mathrm{pos}(P_{d}) \in V(D^k)$ and there exists $1\leq j \leq k$ such that $D_{\ind{1}} \in V(A^j)$. Now we consider two different cases: $j=k$ and $j<k$. 

\vspace{+0.5em}

\textbf{Subcase if $j=k$}: see Figure \ref{fig:lem:exists:nextstraddle}b for a graphical representation of this case. Since $\mathrm{pos}(P_d) \in V(D^k)$ then there exists $\ind{8}\leq d$ such that $\mathrm{pos}(P_{\ind{8}})=D^k_1$. Moreover, since $A^k$ is positive and since $\mathrm{pos}(P_d)-\ensuremath{\overrightarrow{v}} \in V(A^k)$ then there exists $\ind{9}\geq d$ such that $\mathrm{pos}(P_{\ind{9}})-\ensuremath{\overrightarrow{v}}=A^k_{|A^k|}=D^k_1=\mathrm{pos}(P_{\ind{8}})$. Now, let $\ind{1} \leq \ind{7} \leq \ind{2}$ such that $D_{\ind{7}}=A^k_{|A^k|}=D^k_1$ and since $P_{[1,s^+]}\cdot (F+\ensuremath{\overrightarrow{v}})$ is producible by $\mathcal{T}$ then either $P$ is fragile or $P_{[d,\ind{9}]}=F_{[\ind{1},\ind{7}]}+\ensuremath{\overrightarrow{v}}$. Thus $\omeplus{P_{[\ind{8},\ind{9}]}}$ is a sub-assembly of $\omeplus{F_{[\ind{1},\ind{2}]}}$. Since $\dom{P_{[s^-,\ind{8}]}}\subset \mathcal{F}^-$ then $P_{[1,\ind{8}]} \cdot \omeplus{P_{[\ind{8},\ind{9}]}}$ is producible by $\mathcal{T}$ and then the segment $P_{[\ind{8},\ind{9}]}$ of $P$ is pumpable. 

\vspace{+0.5em}

\textbf{Subcase if $j<k$}: see Figure \ref{fig:lem:exists:nextstraddle}a for a graphical representation of this part of the proof. Now, let $n=\ind{2}-\ind{1}$ and $Q=\omeplus{D_{[\ind{1},\ind{2}]}}$ then $Q_{[1,n]}$ is a subgraph of $\mathcal{F}^-$, $Q_{[n,+\infty]}$ is a subgraph of $\mathcal{F}^+$ and $y_{Q_{[n,+\infty]}}=y_{F_{[\ind{1},\ind{2}]}}+y_{\ensuremath{\overrightarrow{v}}} \geq y_{P_{[s^-,|P|]}}+\ensuremath{\overrightarrow{v}} >y_{P_{|P|}}$, then we have $V(Q) \cap V(W_{[m,+\infty]})=\emptyset$. If $j<k$ then let $\ind{1} \leq \ind{10} \leq \ind{2}$ such $D_{\ind{10}}=A^{k}_{|A^k|}$, then there exists $s^+ \leq \ind{11} \leq |P|$ such that $D_{\ind{10}}+\ensuremath{\overrightarrow{v}}=\mathrm{pos}(P_{\ind{11}})$. Moreover, since the decomposition $(A^i)_{1\leq i \leq \ell}$ is positive then $d<\ind{11}$ and then $\mathrm{pos}(P_{\ind{11}}) \in \mathcal{F}^+$ . Thus, $\mathrm{pos}(P_{\ind{11}}) \in V(Q_{[n+1,\infty]})$. Now, since $V(Q) \cap V(W_{[m,+\infty]})=\emptyset$ then there exists $\ind{12}\geq n$ such that $Q_{\ind{12}}=\max\{i: Q_i \in V(W)\}$. Moreover since $\ind{11}>d$ and $\mathrm{pos}(P_{\ind{11}}) \in V(Q_{[n+1,\infty]})$ then $\ind{12}>n$. Now, since $V(Q) \cap V(W_{[m,+\infty]})=\emptyset$ and $Q_{\ind{12}} \in \mathcal{F}^+$ then there exists $d<d'<|P|$ such that $\mathrm{pos}(P_{d'})=Q_{\ind{12}}$. Then, let $C'=Q_{[\ind{12},\ind{12}+n]}$ be a path of direction $\ensuremath{\overrightarrow{v}}$. By definition of $\ind{12}$ and $Q$, the free zone $\mathcal{F}$ is split at position $\mathrm{pos}(P_{d'})$ by $\omeplus{C'}$ into $(\mathcal{F}'^-, \mathcal{F}'^+)$. Note that since $Q_n=P_d$ with $d<d'$ then $Q_n \in V(\mathcal{F}'^-)$. Moreover, since $Q_{[1,\ind{12}]}$ is a path of $\mathcal{F}$ and since $V(Q_{[1,\ind{12}]}) \cap V(\omeplus{C'})=\{Q_{\ind{12}}\}$ then $Q_{[1,\ind{12}]}$ is a subgraph of $\mathcal{F}'^-$ and since $\ind{12}> n$ then $C'-\ensuremath{\overrightarrow{v}}=Q_{[\ind{12}-n,\ind{12}]}$ is a subgraph of $\mathcal{F}'^-$. Thus $P_{d'}$ is a dominant tile and the lemma is true.

This proof is in three parts. In the first one, we define an infinite path which will be useful to split the free zone. In the second part, we show that this path is indeed a subgraph of the free zone. In the last part, we show that the last intersection between this path and $P_{[s^+,|P|]}$ is a dominant tile. See Figure \ref{fig:lem:exists:dom} for an illustration of this proof.

\vspace{+0.5em}

\noindent{\textbf{Definition}}: let $\ensuremath{\overrightarrow{v}}=\overrightarrow{P_{s^-}{P_{s^+}}}$, let $\mathcal{F}$ be the free zone of $P$ associated to $P_{[s^-,s^+]}$ and $W$ be its window, let $p=x_{\ensuremath{\overrightarrow{v}}}+y_{\ensuremath{\overrightarrow{v}}}$. Consider a coherent indexing of this window. Consider the height function $h$ of direction $\ensuremath{\overrightarrow{v}}$. Let $H=\max\{h(\mathrm{pos}(P_i)): s^- \leq i \leq |P| \text{ and $y_{P_i}\geq y_{P_{s^-}}$}\}$. Let $(D^H,U^H)$ be the the cut of the grid by the line of direction $\ensuremath{\overrightarrow{v}}$ and height $H$ and let $L^H$ be its window. 
Now, since the height of $P_{s^-}$ is less than $H$ then the infinite line $W_{[-\infty,0]}$ intersects with $L^H$. Consider an indexing of $L^H$ such that $L^H_0 \in W_{[-m,0]}$, $L^H_1 \notin W_{[-m,0]}$ and $L^H_{p}=L^H_0+\ensuremath{\overrightarrow{v}}$. Now, let $$H'=\max\{h(\mathrm{pos}(P_i)): s^- \leq i \leq |P| \text{ and there exists $k\geq 0$ such that $y_{P_i}=y_{P_{s^-}}+ky_{\ensuremath{\overrightarrow{v}}}$}\}.$$ By definition $H'\leq H$. Now, we define the path $R$ as follow: we definite the positions $A$ and $B$ such that $y_{A}=y_{P_{s^-}}$ and $h(A)=H'$ and $B=A+(0,1)$ then $R$ is the concatenation of the four paths $R^1\cdot R^2 \cdot R^3 \cdot R^4$ defined as:
\begin{itemize}
\item $R^1$ is the path such that $R^1_1=L^H_{0}$, $R^1_{|R^1|}=A$ and for all $1\leq i \leq |R^1|-1$, we have $R^1_{i+1}=R^1_{i}+(1,0)$;
\item $R^2$ is the path from $A$ to $B$ ($R^2$ is made of two vertices and one edges);
\item $R^3$ is the path such that $R^3_1=B$, $R^3_{|R^3|}=L^H_1$ and for all $1\leq i \leq |R^1|-1$, we have $R^3_{i+1}=R^3_{i}-(1,0)$;
\item $R^4$ is the path $L^H_{[1,p]}$.
\end{itemize}




































































































































































































\vspace{+0.5em}

\noindent\textbf{The path $\omeplus{R}$ is a subgraph of $\mathcal{F}$}:
If $L^H_{[0,+\infty]}$ is a not subgraph of $\mathcal{F}$ then there exists $s^- \leq \ind{1} \leq |P|$ such that  $h(\mathrm{pos}(P_{\ind{1}}))>H$ and $y_{P_{\ind{1}}}>P_{s^-}$ which contradicts the definition of $H$. Now if $\omeplus{R}$ is not a subgraph of $\mathcal{F}$ then there exists $s^- \leq \ind{1} \leq |P|$ and $k\geq 0$ such that $y_{P_{\ind{1}}}=y_{P_{s^-}}+ky_{\ensuremath{\overrightarrow{v}}}$ and  $x_{P_{\ind{1}}}>x_{A}+kx_{\ensuremath{\overrightarrow{v}}}$ which contradicts the definition of $H'$.



\vspace{+0.5em}

\noindent\textbf{There exists a dominant tile}: let $Q=\omeplus{R}$, by definition of $R$ and $H'$ there exists an index $\ind{3} \in \mathbb{N}$ and $k\geq0$ such that $Q_{\ind{3}} \in \dom{P_{[s^-,|P|]}}$ and $y_{Q_{\ind{3}}} = y_{P_{s^-}}+k\ensuremath{\overrightarrow{v}}$. Note that if $k=0$ then since $P_{s^-}$ is visible from the west, we have $Q_{\ind{3}}=\mathrm{pos}(P_{s^-})$. In this case, $Q_{\ind{3}+|R|-1}=P_{s^+}$ and then we can suppose that $k>0$ and that $\ind{3}\geq |R|$. Remark that $V(Q_{[|R|,+\infty]}) \cap V(W_{[m,+\infty]})=\emptyset$ otherwise we would have $y_{P_{|P|}}\geq y_{P_{[s^-,|P|]}}+y_{\ensuremath{\overrightarrow{v}}}$ which contradicts the definition of a U-turn. Now, let $\ind{4}=\max\{i: Q_i \in V(W_{[0,+\infty]})\}$. By definition $\ind{4} \geq \ind{3} \geq |R|$ and then $y_{Q_{\ind{4}}} \geq y_{P_{s^+}}$. Also, since $V(Q_{[|R|,+\infty]}) \cap V(W_{[m,+\infty]})=\emptyset$, there exists $s^- \leq d\leq |P|$ such that $P_{d}=Q_{\ind{4}}$. Now if $d < s^+$ then let $(G_1,G_2)$ be the cut of the grid by the underlying path of $P_{[s^-,s^+]}$ whose extremities are both visible from the west and let $W'$ be its window. Consider an indexing of $W'$ coherent with $P_{[s^-,s^+]}$ and suppose that $G_1$ is the left side of $W'$, thus $G_1$ is a subgraph of $\mathcal{F}$. Then $Q_{\ind{4}}$ belongs to $G_1$. Moreover, since $y_{Q_{\ind{4}}} \geq y_{s^+}$, since $Q_{\ind{4}}\neq \mathrm{pos}(P_{s^+})$ and since $Q$ is a subgraph of $\mathcal{F}$ then $Q_{[\ind{4},+\infty]}$ is a subgraph of $G_1$. But $Y_{G_1}=Y_{P_{[s^-,s^+]}}$
 is finite which contradicts the definition of $Q$. Then, $d\geq s^+$ and let $C=Q_{[\ind{4},\ind{4}+|R|-1]}$. Since $Q$ is a subgraph of $\mathcal{F}$ and by definition of $\ind{4}$, then $\omeplus{C}$ splits the free zone into $(\mathcal{F}^-,\mathcal{F}^+)$. Moreover $Q_{[0,\ind{4}]}$ is a subgraph of $\mathcal{F}$ such that $Q_0 \in W_{[-\infty,0]}$ and then  $Q_{[0,\ind{4}]}$ is a subgraph of $\mathcal{F}^-$. Since $\ind{4} \geq |R|$ then $C-\ensuremath{\overrightarrow{v}}=Q_{[\ind{4}-|R|+1,\ind{4}]}$ is a subgraph of $\mathcal{F}^-$ and thus $P_{d}$ is a dominant tile.

(\ell)$ is defined as the finite cycle $C=\bigcup_{1\leq i \leq 4} Q^i$ where: 
\begin{itemize}
\item $Q^1$ is the path starting in $(0,0)$ and ending in $(0,\ell)$ with for all $1\leq i \leq |Q^1|-1$, we have $Q^1_{i+1}=Q^1_i+(0,1)$; 
\item $Q^2$ is the path starting in $(0,\ell)$ and ending in $(\ell,\ell)$ with for all $1\leq i \leq |Q^2|-1$, we have $Q^2_{i+1}=Q^2_i+(1,0)$; 
\item $Q^3$ is the path starting in $(\ell,\ell)$ and ending in $(\ell,0)$ with for all $1\leq i \leq |Q^3|-1$, we have $Q^3_{i+1}=Q^3_i+(0,-1)$; 
\item $Q^4$ is the path starting in $(\ell,0)$ and ending in $(0,0)$ with for all $1\leq i \leq |Q^4|-1$, we have $Q^4_{i+1}=Q^4_i+(-1,0)$.

This proof is done in three steps. During the first step, we initialize different tools (seed constraint, fork) to set up a good setting. During the second step, we build the first stake and during the third one we build the second stake. Several incidents may occurs during the construction of the stakes but anyone of these problems leads to the fragility or pumpability of~$P$. 

\vspace{+0.5em}

\noindent \textbf{Initialization:}


see Figures \ref{fig:proof:stakes2} and \ref{fig:proof:stakes2:2} for an illustration of this part of the proof. By the seed lemma (lemma \ref{macro:seed}), we have $\dom{\sigma} \subset \mathcal{R}(\mathcal{B}^\sigma)$ or $P$ is fragile or pumpable. 

By lemma \ref{lem:true:init}, either $P$ is fragile or pumpable or there exists $1\leq s^-< s^+ \leq \ind{4}$ such that $P_{[s^-,s^+]}$ is a visible candidate segment of direction $\ensuremath{\overrightarrow{v}}$ such that $||\ensuremath{\overrightarrow{v}}||\leq \mathcal{B}$ and $\dom{P_{[1,s^+]}} \subset \mathcal{R}(\mathcal{B}^v)$. By the definition of macroscopic initial conditions, there exists $1\leq \ind{4} \leq |P|$ such that $\ind{4}=\min\{i:y_{P_i} = f^r(\mathcal{B}^v+\mathcal{B})+\mathcal{B}+1)\}$. Note that $s^+ \leq \ind{4}$ and remark that by definition of $\ind{4}$, the path assembly $P_{[1,\ind{4}]}$ is an exposed path assembly (with a turn back of $Y_{P_{[1,\ind{4}]}}$). Now either $\dom{P_{[1,\ind{4}]}} \subset \mathcal{R}(f^b(f^r(\mathcal{B}^v+\mathcal{B})+\mathcal{B}+1))$ or not. In the second the case, $P_{[1,\ind{4}]}$ fits in a band and by lemma \ref{lem:thin}, $P$ is fragile or pumpable. Otherwise, $\dom{P_{[1,\ind{4}]}} \subset \mathcal{R}(f^b(f^r(\mathcal{B}^v+\mathcal{B})+\mathcal{B}+1))$ and by applying lemma \ref{lem:fork} to $P_{[1,\ind{4}]}$, either $P$ is fragile or pumpable or there exists a fork $F$ such that $y_{F_{|F|}}+y_{\ensuremath{\overrightarrow{v}}}\geq f^r(\mathcal{B}^v+\mathcal{B})+\mathcal{B}+1$ and $\dom{F} \subset \mathcal{R}(f^b(f^r(\mathcal{B}^v+\mathcal{B})+\mathcal{B}+1) +\mathcal{B})$. Since $||\ensuremath{\overrightarrow{v}}||\leq \mathcal{B}$, we have $y_{F_{|F|}} \geq f^r(\mathcal{B}^v+\mathcal{B})+1$.

\vspace{+0.5em}

\noindent \textbf{Finding the first stake:} By definition of $F$, there exists $\ind{1}$ such that $\ind{1}=\min\{i:y_{F_i}=f^r(\mathcal{B}^v+\mathcal{B})+1\}$. By definition of a fork, there exists $1 \leq \ind{2} \leq \ind{4}$ such that $F_{\ind{1}}=P_{\ind{2}}$ or $F_{\ind{1}}=P_{\ind{2}}-\ensuremath{\overrightarrow{v}}$. We suppose that $F_{\ind{1}}=P_{\ind{2}}-\ensuremath{\overrightarrow{v}}$ (the other case is symmetric). Remark that $y_{P_{\ind{2}}}\geq f^r(\mathcal{B}^v+\mathcal{B})+1$ and thus $\mathrm{pos}(P_{\ind{2}}) \notin \mathcal{R}(f^r(\mathcal{B}^v+\mathcal{B})+1)$. Now, two cases occur either $P_{[1,s^-]}\cdot F_{[1,\ind{1}]} \cdot (P_{[\ind{2},|P|]}-\ensuremath{\overrightarrow{v}})$ is a path assembly producible by $\mathcal{T}$ or not. In the second case, since by definition of a fork, the path assembly $P_{[1,s^-]}\cdot F$ is producible by $\mathcal{T}$, then $P_{[\ind{2},|P|]}-\ensuremath{\overrightarrow{v}}$ creates a collision with either $F_{[1,\ind{1}]}$ or $P_{[1,s^-]} \cup \sigma$. If $P_{[\ind{2},|P|]}-\ensuremath{\overrightarrow{v}}$ creates a collision with $F_{[1,\ind{1}]}$ (see Figures \ref{fig:proof:stakes3:3:1} and \ref{fig:proof:stakes3:3:2}), by definition of a fork the path assembly $P_{[1,s^+]}\cdot (F+\ensuremath{\overrightarrow{v}})$ is producible by $\mathcal{T}$ and this path assembly creates a collision with $P_{[\ind{2},|P|]}$ and thus $P$ is fragile. If $P_{[\ind{2},|P|]}-\ensuremath{\overrightarrow{v}}$ creates a collision with $P_{[1,s^-]} \cup \sigma$ (see Figures \ref{fig:proof:stakes3:2:1} and \ref{fig:proof:stakes3:2:2}), there exists $\ind{2} \leq \ind{3} \leq |P|$ such that $\mathrm{pos}(P_{\ind{3}})-\ensuremath{\overrightarrow{v}} \in \mathcal{R}(\mathcal{B}^v)$ and thus $\mathrm{pos}(P_{\ind{3}}) \in \mathcal{R}(\mathcal{B}^v+\mathcal{B})$. Then $P$ does not satisfies the reset constraint for $\mathcal{B}^v+\mathcal{B}$ and by the reset lemma \ref{macro:reset}, $P$ is fragile or pumpable. Then, the path assembly $P_{[1,s^-]}\cdot F_{[1,\ind{1}]} \cdot P_{[\ind{2},|P|]}-\ensuremath{\overrightarrow{v}}$ is producible by $\mathcal{T}$ (see Figure \ref{fig:proof:stakes3:1}). Let $\mathcal{S}^-= P_{[1,s^-]} \cdot F_{[1,\ind{1}]}$ be the first stake. Moreover, since $\mathcal{B}^-=f^b(f^r(\mathcal{B}^v+\mathcal{B})+\mathcal{B}+1)+\mathcal{B}$, then $\dom{\mathcal{S}^-} \subset \mathcal{R}(\mathcal{B}^-)$.


\vspace{+0.5em}

\noindent \textbf{Finding the second stake:}
see Figure \ref{fig:proof:stakes4} for an illustration of this part of the proof. By definition of index $\ind{4}$ and since $\ind{2}\leq \ind{4}$, there exist two indices $\ind{2} \leq \ind{5} \leq |P|$ and $\ind{5} \leq \ind{8} \leq |P|$ such that $\ind{5}=\min\{i \geq \ind{2}: \mathrm{pos}(P_i) \notin \mathcal{R}(f^r(\mathcal{B}^-+\mathcal{B}))\}$ and $\ind{8}=\min\{i \geq \ind{5}: \mathrm{pos}(P_i) \notin \mathcal{R}(f^j(f^r(\mathcal{B}^-+\mathcal{B}+1))\}$. Then either $P_{[\ind{5},\ind{8}]}-\ensuremath{\overrightarrow{v}}$ and $P_{[\ind{5},\ind{8}]}$ intersect or not. In the second case, since $\dom{P_{[1,\ind{5}]}} \subset \mathcal{R}(f^r(\mathcal{B}^-+\mathcal{B}+1))$ then by the jail lemma (lemma \ref{macro:jailed}), $P$ is fragile or pumpable. In the second case, there exists $\ind{5} \leq \ind{6}\leq \ind{8}$ and $\ind{5} \leq \ind{7} \leq \ind{8}$ such that $\ind{6}=\min\{i \geq \ind{5}:\mathrm{pos}(P_i)-\ensuremath{\overrightarrow{v}} \in \dom{P_{[\ind{5},\ind{8}]}}\}$ and $\mathrm{pos}(P_{\ind{7}})=\mathrm{pos}(P_{\ind{6}})-\ensuremath{\overrightarrow{v}}$. Moreover, $\dom{P_{[\ind{2},\ind{6}]}} \subset \mathcal{R}(f^j(f^r(\mathcal{B}^-+\mathcal{B}+1))+1)$. Now, since $\mathcal{S}^- \cdot (P_{[\ind{2},\ind{6}]}-\ensuremath{\overrightarrow{v}})$ is producible by $\mathcal{T}$ then either $P$ is fragile or $P_{\ind{7}}=P_{\ind{6}}-\ensuremath{\overrightarrow{v}}$ and then $P_{\ind{7}}+\ensuremath{\overrightarrow{v}}=P_{\ind{6}}$. Then either $P_{[1,\ind{6}]} \cdot (P_{[\ind{7},|P|]}+\ensuremath{\overrightarrow{v}})$ is a path assembly producible by $P$ or not. In the first case $\mathcal{S}^+=P_{[1,\ind{6}]}$ is our second stake and the lemma is true since $\dom{\mathcal{S}^+} \subset \mathcal{R}(f^j(f^r(\mathcal{B}^-+\mathcal{B}+1))+\mathcal{B}+1)$ and $\mathcal{B}^s=f^j(f^r(\mathcal{B}^-+\mathcal{B}+1))+\mathcal{B}+1$ (see Figure \ref{fig:proof:stakes5:1}). Otherwise, $P_{[\ind{7},|P|]}+\ensuremath{\overrightarrow{v}}$ collides with $P_{[1,\ind{6}]} \cup \sigma$. If the collision occurs between $P_{[\ind{7},|P|]}+\ensuremath{\overrightarrow{v}}$ and $P_{[1,\ind{2}]} \cup \sigma$ then there exists $\ind{7} \leq \ind{9} \leq |P|$ such that $\mathrm{pos}(P_{\ind{9}}+\ensuremath{\overrightarrow{v}}) \in \mathcal{R}(\mathcal{B}^-)$ and then $\mathrm{pos}(P_{\ind{9}}) \in \mathcal{R}(\mathcal{B}^-+\mathcal{B})$ (see Figures \ref{fig:proof:stakes5:2:1} and \ref{fig:proof:stakes5:2:2}). Since $\ind{9}\geq \ind{7} \geq \ind{5}$ and since $\mathrm{pos}(P_{\ind{5}}) \notin \mathcal{R}(f^r(\mathcal{B}^-+\mathcal{B}))$ then $P$ does not satisfies the reset constraint for $\mathcal{B}^-+\mathcal{B}$ and by the reset lemma \ref{macro:reset}, $P$ is fragile or pumpable. Otherwise there exists a collision between $P_{[\ind{7},|P|]}+\ensuremath{\overrightarrow{v}}$ and $P_{[\ind{2},\ind{6}]}$ and then there exists a collision between $P_{[\ind{7},|P|]}$ and $P_{[\ind{2},\ind{6}]}-\ensuremath{\overrightarrow{v}}$ (see Figures \ref{fig:proof:stakes5:3:1} and \ref{fig:proof:stakes5:3:2}). Since $\mathcal{S}^- \cdot (P_{[\ind{2},\ind{6}]}-\ensuremath{\overrightarrow{v}})$ is producible by $\mathcal{T}$ then $P$ is fragile.
